let language = localStorage.getItem('michustudio_lang') || 'es';
let token = localStorage.getItem(STORAGE_TOKEN) || '';
let currentUser = readStoredUser();
let authMode = 'login';
let toastTimer = 0;
function readStoredUser(){try{return JSON.parse(localStorage.getItem(STORAGE_USER)||'null')}catch{return null}}
function t(key){return (translations[language]||translations.es)[key] || translations.es[key] || key}
function applyLanguage(){document.documentElement.lang=language==='pt-BR'?'pt-BR':language;document.querySelectorAll('[data-i18n]').forEach(el=>{const key=el.dataset.i18n;const value=t(key);if(el.tagName==='INPUT'||el.tagName==='TEXTAREA'){el.placeholder=value}else{el.innerHTML=value}});document.querySelectorAll('[data-i18n-placeholder]').forEach(el=>el.placeholder=t(el.dataset.i18nPlaceholder));document.getElementById('language').value=language;localStorage.setItem('michustudio_lang',language);renderAccountState();}
function showToast(message){const toast=document.getElementById('toast');toast.textContent=message;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),3200)}
function esc(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
async function api(path,options={}){
  const headers=new Headers(options.headers||{});
  if(token)headers.set('Authorization','Bearer '+token);
  if(options.body && !(options.body instanceof FormData)&&!headers.has('Content-Type'))headers.set('Content-Type','application/json');
  let response;
  try{response=await fetch(API+path,{...options,headers,credentials:'same-origin'})}
  catch{throw new Error('No se pudo conectar con el servidor. Revisá tu conexión y probá de nuevo.')}
  let data={},raw='';
  try{const body=await response.text();try{data=JSON.parse(body)}catch{raw=body}}catch{}
  if(!response.ok){
    if(response.status===401&&token){token='';currentUser=null;localStorage.removeItem(STORAGE_TOKEN);localStorage.removeItem(STORAGE_USER);renderAccountState()}
    let fallback=`El servidor respondió con el error ${response.status}.`;
    if(response.status===404)fallback='El servidor de cuentas no reconoce esa ruta. Revisá que esté desplegada la versión correcta.';
    if(response.status===502||response.status===503)fallback='El servidor de cuentas no está respondiendo. Probá de nuevo en un rato.';
    throw new Error(data.error||fallback)
  }
  return data
}
function saveUser(user){currentUser=user;localStorage.setItem(STORAGE_USER,JSON.stringify(user));renderAccountState()}
function persistSession(data){if(data&&typeof data.token==='string'&&data.token){token=data.token;localStorage.setItem(STORAGE_TOKEN,token)}}
function go(page){document.querySelectorAll('.page').forEach(el=>el.classList.toggle('active',el.id==='page-'+page));document.querySelectorAll('.nav-link').forEach(el=>el.classList.toggle('active',el.dataset.page===page));document.querySelectorAll('.bottom-link[data-page]').forEach(el=>el.classList.toggle('active',el.dataset.page===page));document.getElementById('mobileMenu').setAttribute('aria-expanded','false');document.querySelector('.main-nav').classList.remove('open');if(page==='account')refreshMe().catch(()=>{});if(page==='community'&&token){loadRequests();loadFriends();loadMail()}if(page==='forum')loadForum();window.scrollTo({top:0,behavior:'smooth'})}
function renderAccountState(){const logged=!!token&&!!currentUser;document.getElementById('openAccount').textContent=logged?currentUser.username:t('account');document.getElementById('authPanel').hidden=logged;document.getElementById('profilePanel').hidden=!logged;document.getElementById('forumAuthHint').textContent=logged?currentUser.username:t('loginToPost');if(!logged)return;document.getElementById('profileName').textContent=currentUser.username||'Michu';document.getElementById('profileRole').textContent=String(currentUser.role||'User').toUpperCase();document.getElementById('profileStatus').textContent=currentUser.statusText||currentUser.description||t('member');document.getElementById('editUsername').value=currentUser.username||'';document.getElementById('editStatus').value=currentUser.statusText||'';document.getElementById('editDescription').value=currentUser.description||'';document.getElementById('editRegion').value=currentUser.region||'';document.getElementById('editAccent').value=/^#[0-9a-f]{6}$/i.test(currentUser.accentColor||'')?currentUser.accentColor:'#a5edc7';document.getElementById('hideRegion').checked=!!currentUser.hideRegion;document.getElementById('hideOnline').checked=!!currentUser.hideOnline;document.getElementById('profileId').textContent=currentUser.id||'—';document.getElementById('memberSince').textContent=currentUser.memberSince?new Date(currentUser.memberSince).toLocaleDateString(): '—';document.getElementById('playTime').textContent=Number(currentUser.hoursPlayed||0)+' h';const avatar=document.getElementById('profileAvatar');const avatarSource=currentUser.profile_picture?API+currentUser.profile_picture:'/Predeterminado.png';avatar.innerHTML=`<img src="${esc(avatarSource)}?v=${Date.now()}" alt="Foto de perfil" onerror="this.onerror=null;this.src='/Predeterminado.png'">`;const banner=document.getElementById('profileBanner');banner.style.backgroundImage=currentUser.profile_banner?`url("${API+currentUser.profile_banner}?v=${Date.now()}")`:'';banner.style.backgroundColor=currentUser.accentColor||'#c9f4dc'}
function showAccountKey(key){const dialog=document.getElementById('messageDialog');document.getElementById('dialogContent').innerHTML=`<span class="pill">ACCOUNT SECURITY</span><h2>${esc(t('accountKeyTitle'))}</h2><p>${esc(t('accountKeyText'))}</p><input id="accountKeyValue" readonly value="${esc(key)}" style="width:100%;padding:12px;border:1px solid #e5ece5;border-radius:10px;background:#f8faf6;color:#20352a"><button id="copyAccountKey" class="button button-dark" style="margin-top:12px">${esc(t('copyKey'))}</button>`;dialog.showModal();document.getElementById('copyAccountKey').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(key);showToast(t('keyCopied'))}catch{document.getElementById('accountKeyValue').select();showToast('Selecciona y copia la clave manualmente.')}})}
async function refreshMe(){if(!token)return;try{const data=await api('/auth/me');if(data.user)saveUser(data.user)}catch(e){if(token)showToast(e.message)}}
function setAuthMode(mode){authMode=mode;document.querySelectorAll('.auth-tab').forEach(el=>el.classList.toggle('active',el.dataset.authMode===mode));document.getElementById('registerExtras').hidden=mode!=='register';document.getElementById('authSubmit').textContent=t(mode==='login'?'login':'register');document.getElementById('authPassword').autocomplete=mode==='login'?'current-password':'new-password'}
async function submitAuth(event){event.preventDefault();const username=document.getElementById('authUsername').value.trim();const password=document.getElementById('authPassword').value;const body={username,password};if(authMode==='register'){body.region=document.getElementById('authRegion').value.trim().toUpperCase();if(body.region&&!/^[A-Z]{2}$/.test(body.region)){showToast(t('regionError'));return}}try{const data=await api(authMode==='login'?'/login':'/register',{method:'POST',body:JSON.stringify(body)});persistSession(data);saveUser(data.user);document.getElementById('authPassword').value='';showToast(t('loggedIn'));if(data.accountKeyGenerated&&data.accountKey)showAccountKey(data.accountKey);await loadRequests();await loadFriends();await loadMail();go('account')}catch(e){showToast(e.message)}}
async function submitProfile(event){event.preventDefault();if(!token||!currentUser)return showToast(t('loginFirst'));const region=document.getElementById('editRegion').value.trim().toUpperCase();if(region&&!/^[A-Z]{2}$/.test(region))return showToast(t('regionError'));const body={userId:currentUser.id,username:document.getElementById('editUsername').value.trim(),statusText:document.getElementById('editStatus').value.trim(),description:document.getElementById('editDescription').value,region,accentColor:document.getElementById('editAccent').value.toUpperCase(),hideRegion:document.getElementById('hideRegion').checked,hideOnline:document.getElementById('hideOnline').checked};try{const data=await api('/profile/update',{method:'POST',body:JSON.stringify(body)});saveUser(data.user);showToast(t('profileUpdated'))}catch(e){showToast(e.message)}}
async function uploadImage(kind,file){if(!file)return;if(!token||!currentUser)return showToast(t('loginFirst'));if(!['image/png','image/jpeg','image/webp','image/avif'].includes(file.type))return showToast('Usá una imagen PNG, JPG, WebP o AVIF.');if(file.size>5*1024*1024)return showToast('La imagen pesa más de 5 MB. Elegí una más liviana.');const body=new FormData();body.append(kind,file);try{showToast(t(kind==='avatar'?'uploadAvatar':'uploadBanner'));const data=await api(`/users/${encodeURIComponent(currentUser.id)}/${kind}`,{method:'POST',body});saveUser(data.user);showToast(kind==='avatar'?'Foto de perfil actualizada.':'Banner actualizado.')}catch(e){showToast(e.message)}finally{const input=document.getElementById(kind==='avatar'?'avatarFile':'bannerFile');if(input)input.value=''}}
async function logout(){if(!token)return;const oldToken=token;try{await api('/logout',{method:'POST',body:JSON.stringify({userId:currentUser?.id||''})})}catch{}token='';currentUser=null;localStorage.removeItem(STORAGE_TOKEN);localStorage.removeItem(STORAGE_USER);renderAccountState();showToast(t('loggedOut'))}
async function changePassword(event){event.preventDefault();if(!currentUser)return showToast(t('loginFirst'));try{const data=await api('/account/password',{method:'POST',body:JSON.stringify({userId:currentUser.id,currentPassword:document.getElementById('currentPassword').value,newPassword:document.getElementById('newPassword').value})});persistSession(data);document.getElementById('passwordForm').reset();showToast(t('passwordUpdated'))}catch(e){showToast(e.message)}}
function avatarUrl(user){return user&&user.profile_picture?API+user.profile_picture:'/predeterminado.png'}
function userRow(user,actions=''){const id=esc(user.id);const avatar=esc(avatarUrl(user)||'/predeterminado.png');const online=user.online?`<small class="online-state"><i class="ti ti-circle-check" aria-hidden="true"></i> ${esc(t('online'))}</small>`:`<small class="offline-state"><i class="ti ti-circle" aria-hidden="true"></i> ${esc(t('offline'))}</small>`;return `<article class="user-row" data-user-id="${id}"><div class="user-row-avatar"><img src="${avatar}" alt="Foto de ${esc(user.username||'usuario')}" onerror="this.onerror=null;this.src='/Predeterminado.png'"></div><div class="user-row-main"><b>${esc(user.username||'Usuario')}</b><small class="user-id">ID · ${esc(id)}</small>${online}</div><div class="user-row-actions">${actions}</div></article>`}
async function searchUsers(){const q=document.getElementById('userSearch').value.trim();const host=document.getElementById('userResults');if(!token)return host.innerHTML=`<p class="muted small">${esc(t('notLoggedIn'))}</p>`;host.innerHTML='<p class="muted small">…</p>';try{const data=await api('/users?q='+encodeURIComponent(q)+'&limit=60');const users=(data.users||[]).filter(u=>u.id!==currentUser.id);if(!users.length){host.innerHTML=`<p class="muted small">${esc(t('searchEmpty'))}</p>`;return}host.innerHTML=users.map(u=>userRow(u,`<button class="mini-button" data-action="view-profile" data-id="${esc(u.id)}">${esc(t('viewProfile'))}</button><button class="mini-button" data-action="add-friend" data-id="${esc(u.id)}">${esc(t('addFriend'))}</button><button class="mini-button secondary" data-action="message-user" data-id="${esc(u.id)}">${esc(t('message'))}</button>`)).join('')}catch(e){host.innerHTML=`<p class="muted small">${esc(e.message)}</p>`}}
async function friendAction(action,friendId){if(!currentUser)return showToast(t('loginFirst'));try{await api('/friends/'+action,{method:'POST',body:JSON.stringify({userId:currentUser.id,friendId})});showToast(t(action==='request'?'friendSent':action==='accept'?'friendAccepted':action==='decline'?'friendDeclined':'saved'));await loadRequests();await loadFriends();await searchUsers()}catch(e){showToast(e.message)}}
async function loadRequests(){const host=document.getElementById('requestsList');if(!token||!currentUser){host.innerHTML=`<p class="muted small">${esc(t('loginToSeeRequests'))}</p>`;return}try{const data=await api('/friends/requests');const incoming=data.incoming||[];const outgoing=data.outgoing||[];if(!incoming.length&&!outgoing.length){host.innerHTML=`<p class="muted small">${esc(t('noRequests'))}</p>`;return}host.innerHTML=incoming.map(u=>userRow(u,`<button class="mini-button" data-action="accept-friend" data-id="${esc(u.id)}">${esc(t('accept'))}</button><button class="mini-button secondary" data-action="decline-friend" data-id="${esc(u.id)}">${esc(t('decline'))}</button>`)).join('')+outgoing.map(u=>userRow(u,`<span class="pill">PENDING</span>`)).join('')}catch(e){host.innerHTML=`<p class="muted small">${esc(e.message)}</p>`}}
async function loadFriends(){const host=document.getElementById('friendsList');if(!token||!currentUser){host.innerHTML=`<p class="muted small">${esc(t('loginToSeeFriends'))}</p>`;return}try{const data=await api('/auth/me');saveUser(data.user);const ids=Array.isArray(data.user.friends)?data.user.friends:[];if(!ids.length){host.innerHTML=`<p class="muted small">${esc(t('noFriends'))}</p>`;return}const profiles=await Promise.all(ids.slice(0,200).map(id=>api('/users/'+encodeURIComponent(id)).catch(()=>null)));const users=profiles.filter(Boolean).map(x=>x.user).filter(Boolean);host.innerHTML=users.map(u=>userRow(u,`<button class="mini-button secondary" data-action="message-user" data-id="${esc(u.id)}">${esc(t('message'))}</button><button class="mini-button secondary" data-action="remove-friend" data-id="${esc(u.id)}">${esc(t('deleteFriend'))}</button>`)).join('')}catch(e){host.innerHTML=`<p class="muted small">${esc(e.message)}</p>`}}
async function loadMail(){const host=document.getElementById('inboxList');if(!token||!currentUser){host.innerHTML=`<p class="muted small">${esc(t('loginToSeeMail'))}</p>`;return}try{const data=await api('/mail/'+encodeURIComponent(currentUser.id)+'?limit=100');const mails=data.mails||[];if(!mails.length){host.innerHTML=`<p class="muted small">${esc(t('noMail'))}</p>`;return}host.innerHTML=mails.map(m=>`<article class="mail-item ${m.isRead?'':'unread'}"><div><b>${esc(m.type==='Warning'?'⚠ Admin':'✉ '+(m.fromUserId||'User'))}</b><p>${esc(m.message)}</p><small>${esc(new Date(m.createdAt).toLocaleString())} · ID ${esc(m.id)}</small></div><div>${m.isRead?'':'<button class="mini-button" data-action="read-mail" data-id="'+esc(m.id)+'">✓</button>'}</div></article>`).join('')}catch(e){host.innerHTML=`<p class="muted small">${esc(e.message)}</p>`}}
async function sendMail(){if(!currentUser)return showToast(t('loginFirst'));const toUserId=document.getElementById('mailTo').value.trim();const message=document.getElementById('mailMessage').value.trim();if(!toUserId||!message)return showToast(t('unknownError'));try{await api('/mail/send',{method:'POST',body:JSON.stringify({userId:currentUser.id,toUserId,type:'Normal',message})});document.getElementById('mailMessage').value='';showToast(t('messageSent'));await loadMail()}catch(e){showToast(e.message)}}
async function loadGames(){const host=document.getElementById('gamesList');try{const response=await fetch('/Juegos.json',{cache:'no-store'});if(!response.ok)throw new Error('No se pudo cargar la lista de juegos');const games=await response.json();if(!Array.isArray(games)||!games.length){host.innerHTML=`<div class="empty-state">${esc(t('downloadUnavailable'))}</div>`;return}host.innerHTML=games.map(game=>{const available=game.available===true&&game.download;const cover=game.id==='michiverse'?'<img src="/patrocinios/michiverse-cover.webp" alt="" loading="lazy">':'<i class="ti ti-device-gamepad-2" aria-hidden="true"></i>';return `<article class="game-card"><div class="game-cover game-cover-green">${cover}</div><div class="game-card-body"><span class="pill">${esc(game.platform||'GAME')}</span><h3>${esc(game.name||'Game')}</h3><p>${esc(game.id==='michiverse'?t('michiverseDesc'):(game.description||''))}</p><p class="muted small">${esc(game.version||'')}</p>${available?`<a class="button button-dark" href="${esc(game.download)}" download>↓ ${esc(language==='pt-BR'?'Baixar':language==='en'?'Download':'Descargar')}</a>`:`<button class="button button-dark" disabled>${esc(t('downloadUnavailable'))}</button>`}</div></article>`}).join('')}catch{host.innerHTML=`<div class="empty-state">${esc(t('downloadUnavailable'))}</div>`}}
async function loadForum(){const host=document.getElementById('forumPosts');host.innerHTML=`<div class="empty-state">${esc(t('loadingPosts'))}</div>`;try{const data=await api('/forum/posts?limit=50');const posts=data.posts||[];if(!posts.length){host.innerHTML=`<div class="empty-state">${esc(t('noPosts'))}</div>`;return}host.innerHTML=posts.map(p=>`<article class="forum-post" data-post-id="${esc(p.id)}"><div class="post-meta"><span class="post-avatar"><i class="ti ti-user-circle" aria-hidden="true"></i></span><b>${esc(p.username)}</b><span>· ${esc(new Date(p.createdAt).toLocaleString())}</span></div><h3>${esc(p.title)}</h3><p>${esc(p.body)}</p><div class="post-actions"><button class="comment-toggle" data-action="toggle-comments" data-id="${esc(p.id)}">${esc(t('openComments'))} (${Number(p.commentCount)||0})</button></div><div class="comments-box" id="comments-${esc(p.id)}"><div class="comments-list"></div><form class="comment-form" data-post-id="${esc(p.id)}"><input maxlength="1500" placeholder="${esc(t('commentPlaceholder'))}" required><button>${esc(t('comment'))}</button></form></div></article>`).join('')}catch(e){host.innerHTML=`<div class="empty-state">${esc(e.message)}</div>`}}
async function publishPost(){if(!currentUser)return showToast(t('loginFirst'));const title=document.getElementById('postTitle').value.trim();const body=document.getElementById('postBody').value.trim();if(title.length<3||body.length<3)return showToast(t('unknownError'));try{await api('/forum/posts',{method:'POST',body:JSON.stringify({userId:currentUser.id,title,body})});document.getElementById('postTitle').value='';document.getElementById('postBody').value='';showToast(t('postPublished'));await loadForum()}catch(e){showToast(e.message)}}
async function loadComments(postId){const box=document.getElementById('comments-'+postId);const list=box.querySelector('.comments-list');try{const data=await api('/forum/posts/'+encodeURIComponent(postId)+'/comments');list.innerHTML=(data.comments||[]).map(c=>`<div class="comment-item"><b>${esc(c.username)}</b><span>${esc(c.body)}</span></div>`).join('')||`<p class="muted small">${esc(t('noPosts'))}</p>`}catch(e){list.textContent=e.message}}
async function wikiPage(key){document.querySelectorAll('.wiki-tab').forEach(el=>el.classList.toggle('active',el.dataset.wiki===key));const article=document.getElementById('wikiArticle');const pages={
start:`<span class="pill">DOCUMENTACIÓN</span><h2>MichuStudio</h2><p>MichuStudio reúne juegos, herramientas y espacios para la comunidad. Esta Wiki documenta el proyecto y evita presentar características planificadas como si ya estuvieran publicadas.</p><div class="wiki-cards"><button class="wiki-info-card" data-wiki-card="michiverse"><i class="ti ti-box-multiple"></i><b>Michiverse</b><span>Juego voxel para Android en desarrollo</span></button><button class="wiki-info-card" data-wiki-card="performance"><i class="ti ti-gauge"></i><b>Rendimiento</b><span>Meshing, caché y carga de chunks</span></button><button class="wiki-info-card" data-wiki-card="team"><i class="ti ti-code"></i><b>Desarrollo</b><span>Equipo y objetivos</span></button></div><div class="wiki-tip"><i class="ti ti-info-circle"></i><span>Las imágenes de la sección de material gráfico son conceptuales; no son capturas reales del juego.</span></div>`,
michiverse:`<span class="pill">PROYECTO PRINCIPAL</span><h2>Michiverse</h2><p>Michiverse es un juego de bloques para Android, con un mundo voxel, biomas, bloques y sistemas propios. Se desarrolla para funcionar en dispositivos móviles, no solo en equipos de escritorio.</p><div class="wiki-feature-image"><img src="/patrocinios/michiverse-cover.webp" alt="Ilustración conceptual de un paisaje voxel de Michiverse"><small>Material promocional conceptual · no representa una captura de juego</small></div><div class="wiki-facts"><div><small>Plataforma objetivo</small><b>Android</b></div><div><small>Estado</small><b>Desarrollo activo</b></div><div><small>Versión base documentada</small><b>Alpha 1.0.0</b></div></div><h3>Enfoque del proyecto</h3><p>El objetivo es construir una identidad propia mediante bloques, biomas y sistemas de mundo, y mantener una experiencia razonable en dispositivos con recursos limitados. La disponibilidad de cada función depende de la versión publicada.</p>`,
performance:`<span class="pill">INGENIERÍA</span><h2>Rendimiento móvil</h2><p>Michiverse combina varias técnicas para evitar trabajo innecesario y controlar el coste de renderizado y generación del mundo.</p><div class="wiki-tech-grid"><section><i class="ti ti-box-model-2"></i><h3>Greedy meshing</h3><p>Agrupa caras visibles compatibles en superficies mayores para reducir la cantidad de geometría que debe enviarse a la GPU.</p></section><section><i class="ti ti-stack-2"></i><h3>Caché de chunks</h3><p>Reutiliza datos de chunks recientes para disminuir regeneraciones y asignaciones repetidas.</p></section><section><i class="ti ti-chart-line"></i><h3>Mapa de alturas</h3><p>Optimiza la construcción del terreno usando la altura del terreno en lugar de tratar todas las columnas como casos independientes.</p></section><section><i class="ti ti-list-check"></i><h3>Cola de trabajos</h3><p>Limita la cantidad de tareas de chunks que se procesan a la vez para reducir picos de CPU y carga térmica.</p></section><section><i class="ti ti-photo"></i><h3>Texturas y mipmaps</h3><p>Usa atlas de texturas y mipmaps para gestionar materiales y reducir problemas al mostrar texturas a distintas distancias.</p></section><section><i class="ti ti-adjustments"></i><h3>Calidad gráfica selectiva</h3><p>El proyecto también contempla o utiliza AO, niebla, sombras de menor resolución y mapas de material; su coste depende de los ajustes y del dispositivo.</p></section></div><div class="wiki-tip"><i class="ti ti-device-mobile"></i><span>Los FPS y la temperatura cambian según el hardware, la escena, la distancia de visión y los ajustes activos. Las optimizaciones no garantizan la misma cifra en todos los teléfonos.</span></div>`,
team:`<span class="pill">EQUIPO</span><h2>Desarrollo y dirección</h2><div class="wiki-team-card"><div class="wiki-team-avatar">MS</div><div><b>MichuStudioOFCIAL</b><span>Desarrollador principal</span><p>Responsable del desarrollo de Michiverse y de la identidad de MichuStudio.</p></div></div><div class="wiki-facts"><div><small>Nombre del equipo</small><b>MichuStudio</b></div><div><small>Área principal</small><b>Desarrollo móvil</b></div><div><small>Infraestructura web</small><b>Render + GitHub</b></div></div><h3>Principios de desarrollo</h3><p>Priorizar el rendimiento móvil, mantener la identidad visual del proyecto, separar las funciones publicadas de las que aún están en desarrollo y conservar los datos de las cuentas existentes durante las actualizaciones.</p>`,
media:`<span class="pill">RECURSOS GRÁFICOS</span><h2>Material promocional</h2><p>Esta carpeta reúne imágenes preparadas para banners, tarjetas promocionales y futuras páginas del proyecto. La imagen actual es una ilustración conceptual, no una captura de gameplay ni una confirmación de una función concreta.</p><div class="wiki-media-grid"><figure><img src="/patrocinios/michiverse-cover.webp" alt="Paisaje voxel conceptual de Michiverse"><figcaption>Michiverse · imagen destacada</figcaption></figure><figure><img src="/patrocinios/michiverse-banner.webp" alt="Recorte panorámico promocional de Michiverse"><figcaption>Michiverse · banner panorámico</figcaption></figure></div><p class="muted small">Archivos ubicados en <code>/patrocinios/</code>. Podés reemplazarlos por artes oficiales o capturas reales cuando estén disponibles.</p>`,
account:`<span class="pill">CUENTAS</span><h2>Tu perfil</h2><p>La cuenta permite editar el nombre visible, el estado, la descripción, la región y el color del perfil, además de subir una foto y un banner.</p><ul class="wiki-list"><li>La sesión se conserva en el navegador entre recargas, mientras el token siga siendo válido.</li><li>Cuando la foto de perfil está vacía, el sitio muestra <code>Predeterminado.png</code> sin guardar esa imagen como foto subida.</li><li>La información privada depende de las opciones de privacidad y de lo que devuelva el servidor.</li></ul><div class="wiki-tip"><i class="ti ti-shield-check"></i><span>No compartas tu contraseña ni los tokens de sesión.</span></div>`,
community:`<span class="pill">COMUNIDAD</span><h2>Foro y mensajes</h2><p>El foro sirve para publicaciones que puede ver la comunidad. La bandeja interna es para mensajes entre cuentas de MichuStudio; no es un correo electrónico externo.</p><div class="wiki-cards"><button class="wiki-info-card" data-page-card="forum"><i class="ti ti-message-circle-2"></i><b>Foro</b><span>Publicaciones y comentarios</span></button><button class="wiki-info-card" data-page-card="community"><i class="ti ti-users"></i><b>Amistades</b><span>Buscar cuentas y gestionar solicitudes</span></button></div><div class="wiki-tip"><i class="ti ti-bell"></i><span>Tratá con respeto a las demás personas y evitá enviar mensajes repetidos.</span></div>`
};article.innerHTML=pages[key]||pages.start;article.querySelectorAll('[data-wiki-card]').forEach(el=>el.addEventListener('click',()=>wikiPage(el.dataset.wikiCard)));article.querySelectorAll('[data-page-card]').forEach(el=>el.addEventListener('click',()=>go(el.dataset.pageCard)))}
async function viewProfile(id){try{const data=await api('/users/'+encodeURIComponent(id));const u=data.user||{};const name=esc(u.username||'Usuario');const avatar=esc(u.profile_picture?API+u.profile_picture:'/Predeterminado.png');const banner=esc(u.profile_banner?API+u.profile_banner:'/patrocinios/michiverse-cover.webp');const role=esc(String(u.role||'Usuario'));const status=esc(u.statusText||'Sin estado');const description=esc(u.description||'Este perfil todavía no tiene una descripción.');const statusVisible=!u.hideOnline;const regionVisible=!u.hideRegion;const region=regionVisible&&u.region?esc(u.region):'';const memberSince=u.memberSince?esc(new Date(u.memberSince).toLocaleDateString()):'Sin dato';const hours=u.hoursPlayed!==undefined&&u.hoursPlayed!==null?esc(String(u.hoursPlayed))+' h':'Sin dato';const presence=statusVisible?`<span class="public-presence ${u.online?'is-online':'is-offline'}"><i class="ti ${u.online?'ti-circle-check':'ti-circle'}" aria-hidden="true"></i>${esc(u.online?t('online'):t('offline'))}</span>`:'';const regionChip=region?`<span class="profile-chip"><i class="ti ti-map-pin" aria-hidden="true"></i>${region}</span>`:'';document.getElementById('dialogContent').innerHTML=`<article class="public-profile"><div class="public-profile-banner"><img src="${banner}" alt="Banner de ${name}" onerror="this.onerror=null;this.src='/patrocinios/michiverse-banner.webp'"></div><div class="public-profile-heading"><img class="public-profile-avatar" src="${avatar}" alt="Foto de ${name}" onerror="this.onerror=null;this.src='/Predeterminado.png'"><div class="public-profile-name"><div class="public-profile-badges"><span class="role-chip"><i class="ti ti-rosette" aria-hidden="true"></i>${role}</span>${presence}</div><h2>${name}</h2><p>${status}</p></div><button class="button button-soft public-message" data-action="message-user" data-id="${esc(u.id||id)}"><i class="ti ti-mail" aria-hidden="true"></i> Mensaje</button></div><div class="public-profile-body"><section class="public-profile-about"><h3><i class="ti ti-align-left" aria-hidden="true"></i> Sobre mí</h3><p>${description}</p></section><section class="public-profile-stats"><div><i class="ti ti-calendar" aria-hidden="true"></i><small>Miembro desde</small><b>${memberSince}</b></div><div><i class="ti ti-device-gamepad-2" aria-hidden="true"></i><small>Tiempo de juego</small><b>${hours}</b></div><div><i class="ti ti-id" aria-hidden="true"></i><small>ID de cuenta</small><b>${esc(u.id||id)}</b></div></section>${(regionChip||!statusVisible)?`<div class="public-profile-details">${regionChip}${!statusVisible?'<span class="profile-chip"><i class="ti ti-eye-off" aria-hidden="true"></i>Estado oculto</span>':''}</div>`:''}</div></article>`;document.getElementById('messageDialog').showModal()}catch(e){showToast(e.message)}}
async function handleDelegated(event){const button=event.target.closest('[data-action]');if(button){const id=button.dataset.id;switch(button.dataset.action){case'view-profile':return viewProfile(id);case'add-friend':return friendAction('request',id);case'accept-friend':return friendAction('accept',id);case'decline-friend':return friendAction('decline',id);case'remove-friend':return friendAction('remove',id);case'message-user':{const profileDialog=document.getElementById('messageDialog');if(profileDialog.open)profileDialog.close();go('community');document.getElementById('mailTo').value=id;document.getElementById('mailMessage').focus();return}case'read-mail':try{await api('/mail/'+encodeURIComponent(id)+'/read',{method:'POST',body:JSON.stringify({userId:currentUser.id})});return loadMail()}catch(e){return showToast(e.message)}case'toggle-comments':{const box=document.getElementById('comments-'+id);box.classList.toggle('open');if(box.classList.contains('open'))return loadComments(id)}}}const form=event.target.closest('.comment-form');if(form){event.preventDefault();if(!currentUser)return showToast(t('loginFirst'));const body=form.querySelector('input').value.trim();if(!body)return;try{await api('/forum/posts/'+encodeURIComponent(form.dataset.postId)+'/comments',{method:'POST',body:JSON.stringify({userId:currentUser.id,body})});form.reset();showToast(t('postComment'));await loadComments(form.dataset.postId)}catch(e){showToast(e.message)}}}
async function bootstrap(){document.getElementById('year').textContent=new Date().getFullYear();applyLanguage();setAuthMode('login');renderAccountState();document.querySelectorAll('[data-page]').forEach(el=>el.addEventListener('click',()=>go(el.dataset.page)));document.querySelectorAll('[data-goto]').forEach(el=>el.addEventListener('click',()=>go(el.dataset.goto)));document.getElementById('openAccount').addEventListener('click',()=>go('account'));document.getElementById('quickCreatePost').addEventListener('click',()=>{if(!token){go('account');showToast('Iniciá sesión para publicar en el foro.');return}go('forum');document.getElementById('postTitle').focus()});document.getElementById('mobileMenu').addEventListener('click',()=>document.querySelector('.main-nav').classList.toggle('open'));document.getElementById('language').addEventListener('change',e=>{language=e.target.value;applyLanguage();setAuthMode(authMode);loadGames();loadForum()});document.querySelectorAll('[data-auth-mode]').forEach(el=>el.addEventListener('click',()=>setAuthMode(el.dataset.authMode)));document.getElementById('authForm').addEventListener('submit',submitAuth);document.getElementById('profileForm').addEventListener('submit',submitProfile);document.getElementById('logout').addEventListener('click',logout);document.getElementById('passwordForm').addEventListener('submit',changePassword);document.getElementById('chooseAvatar').addEventListener('click',()=>document.getElementById('avatarFile').click());document.getElementById('chooseBanner').addEventListener('click',()=>document.getElementById('bannerFile').click());document.getElementById('viewMyProfile').addEventListener('click',()=>{if(currentUser)viewProfile(currentUser.id)});document.getElementById('avatarFile').addEventListener('change',e=>uploadImage('avatar',e.target.files[0]));document.getElementById('bannerFile').addEventListener('change',e=>uploadImage('banner',e.target.files[0]));document.getElementById('searchUsers').addEventListener('click',searchUsers);document.getElementById('userSearch').addEventListener('keydown',e=>{if(e.key==='Enter')searchUsers()});document.getElementById('refreshRequests').addEventListener('click',loadRequests);document.getElementById('refreshFriends').addEventListener('click',loadFriends);document.getElementById('refreshMail').addEventListener('click',loadMail);document.getElementById('sendMail').addEventListener('click',sendMail);document.getElementById('publishPost').addEventListener('click',publishPost);document.getElementById('refreshForum').addEventListener('click',loadForum);document.querySelectorAll('[data-wiki]').forEach(el=>el.addEventListener('click',()=>wikiPage(el.dataset.wiki)));wikiPage('start');document.addEventListener('click',handleDelegated);if(token){try{const data=await api('/auth/me');if(data.user)saveUser(data.user)}catch(e){if(token)showToast('La sesión ya no es válida. Iniciá sesión otra vez.')}}await loadGames();await loadForum();if(token){loadRequests();loadFriends();loadMail()}}
document.addEventListener('DOMContentLoaded',bootstrap);
